#include "kernel.hpp"
#include <iostream>
#include <random>
template<class T> std::pair<T,T> oldcalc(const Graph&g,const ld*lx,ld shift){std::vector<T>x(g.E),ms(g.masks.size());T S=0;for(int j=0;j<g.E;j++){x[j]=exponential(T(lx[j]));S+=x[j];}for(size_t k=0;k<ms.size();k++){T ex=-T(shift);unsigned m=g.masks[k];while(m){int j=__builtin_ctz(m);m&=m-1;ex+=T(lx[j]);}ms[k]=exponential(ex);}T v=0,a=0;for(auto&t:g.terms){T U=0,z=0,zz=0;for(int i:t.ids)U+=ms[i];for(int j=0;j<g.E;j++){T p=T(t.co[j])*x[j];z+=p;zz+=absolute(p);}v+=z/U;a+=zz/U;}return{v/S,a/S};}
int main(int ac,char**av){try{std::ifstream in(av[1]);std::string path;int n=0;Q mq=0;MP mm=0;while(in>>path){auto g=load_graph(path,.8);ld lx[14];for(int s=0;s<3;s++){for(int j=0;j<g.E;j++)lx[j]=logl((3+(j*11+g.id)%29)/32.L)-((s&&j<g.L)?s*150.L:0);ld shift=-std::numeric_limits<ld>::infinity();for(auto m:g.masks){ld v=0;for(int j=0;j<g.E;j++)if(m>>j&1)v+=lx[j];shift=std::max(shift,v);}auto q0=oldcalc<Q>(g,lx,shift),q1=calculate_reference<Q>(g,lx,shift);auto p0=oldcalc<MP>(g,lx,shift),p1=calculate_reference<MP>(g,lx,shift);Q eq=absolute(q0.first-q1.first)/(1+q0.second);MP em=absolute(MP(p0.first-p1.first))/(1+p0.second);mq=std::max(mq,eq);mm=std::max(mm,em);if(eq>Q(1e-29L)||em>MP("1e-285"))throw std::runtime_error("fallback disagreement");n++;}}
std::cout<<"{\"checks\":"<<n<<",\"max_error_scaled_by_absolute_term_sum_quad\":\""<<std::setprecision(18)<<ld(mq)<<"\",\"max_error_scaled_by_absolute_term_sum_mp300\":\""<<mm<<"\",\"status\":\"passed\"}\n";}catch(std::exception&e){std::cerr<<e.what()<<'\n';return 2;}}
